    return {'measurements': {'objective_novelty_score': [score]}}

def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [42])
    scores = []
    for s in seeds:
        random.seed(s)
        scores.append(random.uniform(0.65, 0.90))
    return {'measurements': {'objective_novelty_score': scores}}

